// === Tab: mySketch ===
// by SamuelYAN
// more works //
   // https://twitter.com/SamuelAnn0924
   // https://www.instagram.com/samuel_yan_1990/

// Dot and Dash line + shapes

let mySize;
let seed = Math.random() * 1000;
let tile_count = 6;
let margin = 0;
let speed = 5;

// colors
let colors1 = "e3d7a3-f5989d-ea618e-fce4d6-caac71"
  .split("-")
  .map((a) => "#" + a);
let colors2 = "7d483e-b87644-e6d2c9-e45e00-905c40"
  .split("-")
  .map((a) => "#" + a);

let waves;

function setup() {
  // pixelDensity(5);
  //mySize = 600;
  mySize = max(windowWidth, windowHeight);
  createCanvas(mySize, mySize);
  randomSeed(seed);
  background(5);
  mySetup();
}

function draw() {
  randomSeed(seed);
  background(5,99);
  //scale(1.1);
  for (let c of circles) {
    c.run();
  }
}

// easeIN and OUT 01
function easeOut(o) {
  return 1 + sq(o);
  //return 1 + sq(sq(sq(o)));
}

// easeIN and OUT 02
function easeInOut(t) {
  if ((t /= 1 / 2) < 1) return (1 / 2) * t * t * t;
  return (1 / 2) * ((t -= 2) * t * t + 2);
}

// サイズを調整
function mySetup() {
  randomSeed(seed);
  mySize -= margin * 4;
  addCircles();
}

// 
function addCircles() {
  circles = [];
  let r = mySize / tile_count;
  for (let i = 0; i < tile_count; i++) {
    for (let j = 0; j < tile_count; j++) {
      let x = i * r;
      let y = j * r;
      circles.push(new makeCircle(x, y, r));
    }
  }
}

class makeCircle {
  constructor(x, y, r) {
    this.x = x;
    this.y = y;
    this.r = r;
    this.col1 = random(colors1);
    this.col2 = random(colors1);
    this.settime();
    this.dir = random() < 0.5 ? -1 : 1;
    this.speed = 0;
    this.ang = (int(random(4)) * TAU) / 3;
    this.mv = 0;
    this.strWei = random(3);
    this.tog = 0;
    this.move = random(-this.r,this.r);
    //this.move = this.r/2;
    this.rot = 0;
    this.space = random(20,50)

  }

  display() {
    push();
    translate(this.x + this.move, this.y + this.move);
    scale(0.75);
    //rotate(this.ang);
    //strokeCap(PROJECT);
    stroke(this.col1);
    noFill();
    //fill(this.col1);
    strokeWeight(this.strWei);
    rotate(this.rot);
    //this.movepos =  this.move;
    this.newr = this.strWei * this.r;
    drawingContext.setLineDash([10,8,2,8]);
     for (let i = 0; i < 6; i++) {
      rotate(this.rot + i*PI / 2);
      //let space = 10;
      ellipse(
      0,0,
      this.newr-i * this.space,
      this.newr-i * this.space
    );
    }


    pop();
  }

  settime() {
    this.t = -int(random(map(speed, 1, 5, 3000, 100)));
    this.t1 = map(speed, 1, 5, 400, 100);
  }

  update() {
    if (this.t >= 0 && this.t < this.t1) {
      let easePar = norm(this.t, 0, this.t1 - 1);
      this.rot = lerp(0, TAU * this.dir, easeOut(easePar));
      //this.move = lerp(0, TAU * this.dir, easeOut(easePar));
      //this.move = lerp(-1, 1, easeInOut(easePar)) * this.w * (this.tog * 2 - 1);
    }
    if (this.t1 < this.t) {
      this.settime();
    }
    this.t++;
  }

  run() {
    this.display();
    this.update();
  }
}

function mouseClicked(){
  seed = Math.random() * 1000;
  randomSeed(seed);
  //background(245);
  loop();
}

function keyTyped() {
  if (key === "s" || key === "S") {
    noLoop();
    saveCanvas("MovingShapes", "png");
  }
}

